from src.nodes.base import BaseNode
from src.runtime.assets.vector_search import get_vector_search_engine

class Hou_Mcp_Vector_Search(BaseNode):
    name = "hou_mcp_vector_search"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",      "string", widget_type="text", default="search")
        self.add_input("query",       "string", widget_type="text")
        self.add_input("environment", "string", widget_type="text")
        self.add_input("role",        "string", widget_type="text")
        self.add_input("story_role",  "string", widget_type="text")
        self.add_input("cinematic",   "string", widget_type="text")
        self.add_input("top_k",       "int",    widget_type="int", default=10)
        self.add_output("results",  "list")
        self.add_output("total",    "int")
        self.add_output("response", "any")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action      = str(inputs.get("action") or "search").strip().lower()
        query       = str(inputs.get("query") or "").strip()
        environment = str(inputs.get("environment") or "").strip()
        role        = str(inputs.get("role") or "").strip()
        story_role  = str(inputs.get("story_role") or "").strip()
        cinematic   = str(inputs.get("cinematic") or "").strip()
        top_k       = int(inputs.get("top_k") or 10)
        try:
            engine = get_vector_search_engine()
            if action == "search_environment":
                resp = engine.search_environment(environment, top_k=top_k)
            elif action == "search_role":
                resp = engine.search_role(role, top_k=top_k)
            elif action == "search_storytelling":
                resp = engine.search_storytelling(story_role, top_k=top_k)
            elif action == "search_cinematic":
                resp = engine.search_cinematic(cinematic, top_k=top_k)
            elif action == "search_top_k":
                ids = engine.search_top_k(query, k=top_k)
                return {"results": [{'asset_id': i} for i in ids], "total": len(ids), "response": {"asset_ids": ids}, "exec_out": True}
            else:
                filters = {k: v for k, v in {"environment": environment, "role": role}.items() if v}
                resp = engine.search(query, top_k=top_k, filters=filters or None)
            return {"results": resp.results, "total": resp.total, "response": resp.to_dict(), "exec_out": True}
        except Exception as e:
            self.log_error(f"hou_mcp_vector_search failed: {e}")
            return {"results": [], "total": 0, "response": {}, "exec_out": True}

def register_node():
    return Hou_Mcp_Vector_Search
